insert into
    t_tmp_thmanage (guid, userid, createtime, deletetime, isdelete, tablename, tabletype, overarea)
values (#{guid}, #{userID}, now(), null, false, #{newTableName}, #{type}, ${overArea});

CREATE TABLE IF NOT EXISTS ${newTableName}
(
    id integer NOT NULL DEFAULT nextval('${newTableName}_id_seq'::regclass),
    BSM character varying(200) COLLATE pg_catalog.default,
    coverarea double precision,
    coverratio double precision,
    dlmc character varying(20) COLLATE pg_catalog.default,
    reftablename character varying(50) COLLATE pg_catalog.default,
    CONSTRAINT ${newTableName}_pkey PRIMARY KEY (id)
    );
